"""PSLE-style items for sci-energy-conv-forms, all tiers (round sci-fill-energy-conv-2026-11-20)."""
from fillkit import add, table, graph, lint
from figs_energy import echain, track, pendulum, springboard

SUB, FILE = "sci-energy-conv-forms", "sci-energy-conv.json"
EC, FT, RD = "sci-pat-energy-conversion", "sci-pat-fair-test-design", "sci-pat-read-data"
B, I, C = "basic", "intermediate", "competent"
P = []
def q(*a): P.append(a)
def W(t, tag, why): return (t, tag, why)
def tb(h, r, w, c): return lambda: table(h, r, w, c)
def cv(a, b): return f"{a} energy to {b} energy"

# ---------------- basic ----------------
q("ec-001", B, 2, EC, "Which form of energy does a rolling football have?", "Kinetic energy", [W("Potential energy", "wrong-form", "Potential energy is stored energy, for example in an object that is high up. A rolling ball is moving."), W("Light energy", "wrong-form", "A football does not give out light."), W("Electrical energy", "wrong-form", "No electric current flows through a football.")], ["Any moving object has kinetic energy."], None)
q("ec-002", B, 2, EC, "A book rests on a high shelf. Which form of energy does it have because of its height?", "Potential energy", [W("Kinetic energy", "wrong-form", "Kinetic energy is the energy of movement. The book is not moving."), W("Heat energy", "wrong-form", "Being high up does not make the book hot."), W("Sound energy", "wrong-form", "The book is not making any sound.")], ["An object that is high up can fall, so it has gravitational potential energy."], None)
q("ec-003", B, 2, EC, "Which of the following gives out light energy?", "A lit candle", [W("A stretched rubber band", "wrong-form", "It has potential energy stored in it. It does not shine."), W("A ringing school bell", "wrong-form", "A ringing bell gives out sound energy."), W("A rolling marble", "wrong-form", "A rolling marble has kinetic energy. It does not give out light.")], ["A flame gives out light energy, and heat energy too."], None)
q("ec-004", B, 2, EC, "Which of these things gives out sound energy?", "A drum that is being hit", [W("A book lying on a desk", "wrong-form", "It is not moving or vibrating, so it makes no sound."), W("A torch that is switched off", "wrong-form", "A torch gives out light, not sound, and this one is off."), W("A pencil in a pencil case", "wrong-form", "A pencil that is not moving gives out no sound.")], ["A drum skin shakes when it is hit and gives out sound energy."], None)
q("ec-005", B, 2, EC, "Which one of the following is NOT a form of energy?", "Friction", [W("Sound", "is-energy", "Sound is a form of energy. We hear it."), W("Light", "is-energy", "Light is a form of energy. We see with it."), W("Heat", "is-energy", "Heat is a form of energy. It makes things warm.")], ["Friction is a force that acts when two surfaces rub. It is not a form of energy."], None)
q("ec-006", B, 2, EC, "A hairdryer is plugged into a socket and switched on. Which form of energy does the hairdryer take in?", "Electrical energy", [W("Heat energy", "output-not-input", "Heat energy is given out by the hairdryer. It does not come from the socket."), W("Kinetic energy", "output-not-input", "The fan inside moves, so kinetic energy is given out, not taken in."), W("Sound energy", "output-not-input", "The noise it makes is given out, not taken in.")], ["A socket supplies electrical energy. The hairdryer changes it into heat, kinetic and sound energy."], None)
q("ec-007", B, 3, EC, "A ceiling fan is switched on. Which energy conversion takes place?", cv("Electrical", "kinetic"), [W(cv("Kinetic", "electrical"), "reversed", "The fan uses electricity to move. It does not make electricity."), W(cv("Light", "kinetic"), "wrong-form", "The fan does not take in light energy."), W(cv("Electrical", "potential"), "wrong-form", "The blades do not store energy. They move.")], ["The motor changes electrical energy into the kinetic energy of the turning blades."], None)
q("ec-008", B, 3, EC, "A torch is switched on. Which energy conversion mainly takes place in the bulb?", cv("Electrical", "light"), [W(cv("Light", "electrical"), "reversed", "That is what a solar panel does. A torch bulb gives out light."), W(cv("Electrical", "sound"), "wrong-form", "A torch bulb does not make a sound."), W(cv("Electrical", "kinetic"), "wrong-form", "Nothing in the bulb moves.")], ["The bulb changes electrical energy into light energy (and a little heat)."], None)
q("ec-009", B, 3, EC, "A solar panel is placed in bright sunshine. Which energy conversion takes place?", cv("Light", "electrical"), [W(cv("Electrical", "light"), "reversed", "A solar panel makes electricity. It does not make light."), W(cv("Sound", "electrical"), "wrong-form", "A solar panel does not use sound."), W(cv("Light", "kinetic"), "wrong-form", "A solar panel itself does not move.")], ["A solar panel changes light energy from the Sun into electrical energy."], None)
q("ec-010", B, 3, EC, "Sam rubs his hands together quickly and they become warm. Which energy conversion takes place?", cv("Kinetic", "heat"), [W(cv("Heat", "kinetic"), "reversed", "His moving hands make the heat. The heat does not make the hands move."), W(cv("Kinetic", "light"), "wrong-form", "His hands do not shine."), W(cv("Potential", "sound"), "wrong-form", "His hands are not storing energy, and no loud sound is made.")], ["Rubbing is movement against friction, so kinetic energy changes into heat energy."], None)
q("ec-011", B, 3, EC, "A toaster toasts a slice of bread. Which energy conversion mainly takes place in the toaster?", cv("Electrical", "heat"), [W(cv("Heat", "electrical"), "reversed", "The toaster uses electricity to make heat, not the other way round."), W(cv("Electrical", "sound"), "wrong-form", "A toaster does not mainly make sound."), W(cv("Light", "heat"), "wrong-form", "A toaster is not powered by light.")], ["The wires in the toaster become hot when electricity flows, so electrical energy changes to heat energy."], None)
q("ec-012", B, 3, EC, "A loudspeaker plays music. Which energy conversion takes place?", cv("Electrical", "sound"), [W(cv("Sound", "electrical"), "reversed", "That is what a microphone does. A loudspeaker gives out sound."), W(cv("Electrical", "light"), "wrong-form", "A loudspeaker is not made to shine."), W(cv("Heat", "sound"), "wrong-form", "A loudspeaker does not run on heat.")], ["A loudspeaker changes electrical energy into sound energy."], None)
q("ec-013", B, 1, EC, "What is the main source of energy for living things on Earth?", "The Sun", [W("The Moon", "wrong-source", "The Moon only reflects a little sunlight."), W("The wind", "wrong-source", "The wind itself gets its energy from the Sun."), W("The soil", "wrong-source", "Soil gives plants minerals but not the energy they need to make food.")], ["Plants use light from the Sun to make food, and animals eat plants or other animals."], None)
q("ec-014", B, 1, EC, "Which of the following was formed from plants that lived long ago?", "Coal", [W("Wind", "wrong-source", "Wind is moving air. It is not formed from plants."), W("Sunlight", "wrong-source", "Sunlight is light from the Sun, not a fuel formed from plants."), W("Flowing water", "wrong-source", "Flowing water is not formed from plants.")], ["Coal was made from the remains of plants that were buried for millions of years. These plants used energy from the Sun."], None)
q("ec-015", B, 1, EC, "A windmill pumps water from a well. The energy of the wind comes from which source?", "The Sun", [W("The Moon", "wrong-source", "The Moon does not heat the air."), W("The clouds", "wrong-source", "Clouds do not give energy to the air."), W("The sea", "wrong-source", "The sea does not make the wind. The Sun heats air and water unevenly.")], ["The Sun heats the air unevenly, and the warm air rising makes the wind blow."], None)
q("ec-016", B, 2, EC, "A rubber band is stretched and held. Which form of energy does it have?", "Potential energy", [W("Kinetic energy", "wrong-form", "The rubber band is not moving while it is held."), W("Light energy", "wrong-form", "A rubber band does not give out light."), W("Sound energy", "wrong-form", "A rubber band held still makes no sound.")], ["A stretched rubber band stores elastic potential energy."], None)
q("ec-017", B, 2, EC, "Ali rolls the same ball at four different speeds. When does the ball have the most kinetic energy?", "When it rolls the fastest", [W("When it rolls the slowest", "reversed", "The slower the ball, the less kinetic energy it has."), W("When it has just stopped", "wrong-idea", "A ball that has stopped has no kinetic energy."), W("When it rolls at any speed", "wrong-idea", "Kinetic energy gets bigger as the speed gets bigger.")], ["The faster an object moves, the more kinetic energy it has."], None)
q("ec-018", B, 2, EC, "A ball is held at different heights above the floor. At which height does it have the most potential energy?", "80 cm", [W("20 cm", "reversed", "20 cm is the lowest, so it gives the least potential energy."), W("35 cm", "wrong-reading", "A greater height gives more potential energy, and 35 cm is not the highest."), W("50 cm", "wrong-reading", "A greater height gives more potential energy, and 50 cm is not the highest.")], ["The higher the ball, the more potential energy it has. The heights were 20 cm, 35 cm, 50 cm and 80 cm."], None)
q("ec-019", B, 2, EC, "Which of these things has both kinetic energy and potential energy?", "A bird flying high in the sky", [W("A book lying on the floor", "wrong-idea", "It is neither moving nor high up."), W("A parked car on level ground", "wrong-idea", "It is not moving and not high up."), W("A candle that is not lit", "wrong-idea", "It is not moving and not high up.")], ["The bird is moving (kinetic energy) and high above the ground (potential energy)."], None)
q("ec-020", B, 3, EC, "In which of the following is electrical energy changed into light energy?", "A lit lamp", [W("A solar panel on a calculator", "reversed", "A solar panel changes light into electrical energy."), W("A running electric fan", "wrong-form", "A fan changes electrical energy into kinetic energy."), W("A ringing doorbell", "wrong-form", "A doorbell changes electrical energy into sound energy.")], ["A lamp changes electrical energy into light energy."], None)
q("ec-021", B, 3, EC, "A ball is released at P and rolls down the track to Q. Which energy conversion mainly takes place?", cv("Potential", "kinetic"), [W(cv("Kinetic", "potential"), "reversed", "That would happen if the ball went up the slope. It is going down."), W(cv("Heat", "kinetic"), "wrong-form", "The ball is not heated. It speeds up because it goes lower."), W(cv("Potential", "light"), "wrong-form", "The ball does not give out light.")], ["The ball goes lower, so it loses potential energy and gains kinetic energy."], lambda: track("slope", {"P": 0.0, "Q": 0.45}, ball="P"))
q("ec-022", B, 3, EC, "A toy car is pushed and then rolls along the floor until it stops. Into which form of energy is its kinetic energy mainly changed?", "Heat energy", [W("Light energy", "wrong-form", "The toy car does not give out light."), W("Electrical energy", "wrong-form", "No electricity is made as the car slows down."), W("Potential energy", "wrong-form", "The car did not go up, so it did not gain potential energy.")], ["Friction between the wheels and the floor changes the kinetic energy into heat energy."], None)
q("ec-023", B, 1, EC, "Plants use energy from the Sun to make food. Which form of energy from the Sun do plants use?", "Light energy", [W("Sound energy", "wrong-form", "The Sun does not send sound to the Earth."), W("Kinetic energy", "wrong-form", "Plants do not use movement energy from the Sun."), W("Electrical energy", "wrong-form", "The Sun does not give plants electrical energy.")], ["Leaves take in light energy from the Sun to make food."], None)
q("ec-024", B, 3, EC, "Which two forms of energy does a burning candle give out?", "Light and heat", [W("Sound and kinetic", "wrong-form", "A candle flame is silent and does not move anything."), W("Electrical and sound", "wrong-form", "A candle makes no electricity."), W("Potential and kinetic", "wrong-form", "A candle flame is not an object that moves or is lifted.")], ["The flame lights up the room and makes the air around it warm."], None)
q("ec-025", B, 3, EC, "Wind turns the blades of the turbine, which turns the generator and lights the bulb. Which energy conversion takes place in the generator?", cv("Kinetic", "electrical"), [W(cv("Electrical", "kinetic"), "reversed", "That is what a motor does. A generator makes electricity."), W(cv("Heat", "electrical"), "wrong-form", "The generator is turned by moving blades, not heated."), W(cv("Potential", "light"), "wrong-form", "The generator does not give out light. The bulb does.")], ["The turning generator changes kinetic energy into electrical energy."], lambda: echain(["Moving|wind", "Turbine|blades", "Generator", "Lit|bulb"]))

# ---------------- intermediate ----------------
PEND = lambda: pendulum()
q("ec-101", I, 2, EC, "A pendulum bob swings from A to C and passes B, the lowest point. At which position does the bob have the most kinetic energy?", "B", [W("A", "wrong-position", "At A the bob is at its highest point and stops for a moment, so its kinetic energy is the least."), W("C", "wrong-position", "At C the bob is at its highest point and stops for a moment, so its kinetic energy is the least."), W("A and C", "wrong-position", "The bob stops for a moment at A and at C, so it has the least kinetic energy there.")], ["The bob moves fastest at the lowest point B, so its kinetic energy is greatest there."], PEND)
q("ec-102", I, 3, EC, "A pendulum bob swings from A down to B, the lowest point. What happens to its potential energy and kinetic energy?", "Potential energy decreases and kinetic energy increases", [W("Potential energy increases and kinetic energy decreases", "reversed", "Going down loses potential energy and the bob speeds up, so kinetic energy increases."), W("Both potential energy and kinetic energy increase", "wrong-idea", "The bob is going lower, so its potential energy cannot increase."), W("Potential energy stays the same and kinetic energy increases", "wrong-idea", "The bob is lower at B than at A, so its potential energy is less.")], ["As the bob goes lower, potential energy changes into kinetic energy."], PEND)
q("ec-103", I, 3, EC, "A pendulum swings a little lower each time and finally stops. What happens to its energy?", "It is changed into heat by friction at the hook and in the air", [W("It is used up in each swing and disappears from the pendulum", "wrong-idea", "Energy does not disappear. It changes into other forms."), W("It is changed into light energy given out by the bob", "wrong-form", "A pendulum does not give out light as it slows."), W("It goes back into the string and is stored there as potential energy", "wrong-idea", "The string does not store the energy, and the bob does not rise again.")], ["Friction at the hook and the air rubbing against the bob change some energy into heat each swing."], PEND)
q("ec-104", I, 2, EC, "A marble is released at P, rolls down to Q and up the other side to R. At which position does the marble have the most kinetic energy?", "Q", [W("P", "wrong-position", "At P the marble has only just been released, so its kinetic energy is the least."), W("R", "wrong-position", "At R the marble is higher and slower, so it has less kinetic energy than at Q."), W("It is the same at P, Q and R", "wrong-idea", "The marble speeds up going down, so its kinetic energy changes.")], ["Q is the lowest point, where the marble moves fastest."], lambda: track("valley", {"P": 0.0, "Q": 0.5, "R": 0.9}, ball="P"))
q("ec-105", I, 3, EC, "A marble is released at P, rolls down to Q and up the other side. It stops at R, which is lower than P. Why does the marble not reach the height of P?", "Some of its energy is changed to heat by friction", [W("Its energy is changed into light energy", "wrong-form", "A rolling marble does not give out light."), W("Gravity pulls harder on the right-hand side", "wrong-idea", "Gravity pulls with the same force everywhere on the track."), W("The marble gets lighter as it rolls", "wrong-idea", "A marble does not lose matter as it rolls.")], ["Friction changes some of the marble's energy into heat, so it cannot climb as high as P."], lambda: track("valley", {"P": 0.0, "Q": 0.5, "R": 0.9}, ball="P"))
HIL = lambda: track("hills", {"P": 0.0, "Q": 0.3, "R": 0.55}, ball="P")
q("ec-106", I, 2, EC, "A roller-coaster car is released at P and rolls along the track without friction. At which position does the car have the most kinetic energy?", "Q", [W("P", "wrong-position", "The car starts at rest at P, so its kinetic energy is the least."), W("R", "wrong-position", "R is higher than Q, so the car is slower there than at Q."), W("It is the same at P, Q and R", "wrong-idea", "The speed of the car changes along the track, so its kinetic energy changes too.")], ["Q is the lowest position, so the car has lost the most potential energy and moves fastest there."], HIL)
q("ec-107", I, 3, EC, "A roller-coaster car is released at P. Which statement about the car moving from Q to R is correct?", "Kinetic energy is changing into potential energy", [W("Potential energy is changing into kinetic energy", "reversed", "Going up a hill, the car slows down and gains height."), W("Kinetic energy is changing into sound energy only", "wrong-idea", "Most of the change is into potential energy as the car climbs."), W("The car gains both kinetic energy and potential energy", "wrong-idea", "It slows down as it climbs, so its kinetic energy decreases.")], ["From Q to R the car rises and slows down, so kinetic energy changes into potential energy."], HIL)
q("ec-108", I, 2, EC, "Which of the following statements about energy are correct?\nA: A moving car has kinetic energy.\nB: A stretched spring has potential energy.\nC: A lit bulb has no energy.\nD: Sound is not a form of energy.", "A and B only", [W("A and C only", "wrong-idea", "A lit bulb gives out light energy and heat energy, so C is wrong."), W("B and D only", "wrong-idea", "Sound is a form of energy, so D is wrong."), W("C and D only", "wrong-idea", "Both C and D are wrong.")], ["A and B are correct. A lit bulb gives out light and heat, and sound is a form of energy."], None)
q("ec-109", I, 3, EC, "A cyclist pedals and the dynamo lights the lamp. What is the form of energy X in the energy chain shown?", "Electrical energy", [W("Potential energy", "wrong-form", "The dynamo does not lift anything higher or store energy by height."), W("Sound energy", "wrong-form", "The dynamo does not turn the movement into sound."), W("Heat energy", "wrong-form", "Heat is given out as well, but it is not what lights the lamp.")], ["The turning dynamo makes electrical energy, which the lamp changes into light."], lambda: echain(["Kinetic|energy", "X", "Light|energy"], "A bicycle lamp"))
q("ec-110", I, 3, EC, "A lift is raised by an electric motor. In the energy chain shown, which row gives X and Y?", "X: electrical energy; Y: kinetic energy", [W("X: kinetic energy; Y: electrical energy", "reversed", "A motor takes in electricity and gives out movement."), W("X: light energy; Y: kinetic energy", "wrong-form", "A lift motor does not run on light."), W("X: electrical energy; Y: light energy", "wrong-form", "The lift moves up, so it gains kinetic energy, not light.")], ["A motor changes electrical energy into kinetic energy."], lambda: echain(["X", "Electric|motor", "Y"], "A lift"))
q("ec-111", I, 3, EC, "A wind-up toy car is wound up, put on the floor and let go. It moves forward. Which energy conversion mainly takes place?", "Potential energy in the spring to kinetic energy", [W("Kinetic energy to potential energy in the spring", "reversed", "Winding stores energy in the spring. Letting go gives it back as movement."), W("Heat energy to kinetic energy", "wrong-form", "A wind-up toy is not driven by heat."), W("Light energy to potential energy", "wrong-form", "The toy does not use light.")], ["Winding the spring stores potential energy, which changes to kinetic energy as it unwinds."], None)
q("ec-112", I, 3, EC, "A toy car runs on a battery. While it moves, its lights shine and its horn sounds. Which forms of energy is the electrical energy changed into?", "Kinetic, light and sound energy", [W("Kinetic and light energy only", "missing-form", "The horn gives out sound, so sound energy must be included."), W("Light and sound energy only", "missing-form", "The car moves, so kinetic energy must be included."), W("Potential, light and sound energy", "wrong-form", "The car does not store energy by going higher, so there is no potential energy.")], ["The motor gives kinetic energy, the lights give light and the horn gives sound."], None)
q("ec-113", I, 3, EC, "Which of the following change electrical energy into heat energy?\nA: An electric iron\nB: A radio\nC: A rice cooker\nD: A ceiling fan", "A and C only", [W("A and B only", "wrong-device", "A radio changes electrical energy into sound."), W("B and D only", "wrong-device", "A radio gives sound and a fan gives movement."), W("C and D only", "wrong-device", "A fan changes electrical energy into movement.")], ["An electric iron and a rice cooker are heated by electricity."], None)
q("ec-114", I, 3, EC, "The table shows the energy conversions in four devices. Which device is shown wrongly?", "The solar cell", [W("The electric fan", "correct-row", "A fan does change electrical energy into kinetic energy."), W("The radio", "correct-row", "A radio does change electrical energy into sound energy."), W("The torch", "correct-row", "A torch does change electrical energy into light energy.")], ["A solar cell changes light energy into electrical energy. The table shows it the wrong way round."], tb(["Device", "Energy in", "Useful energy out"], [["Electric fan", "electrical", "kinetic"], ["Radio", "electrical", "sound"], ["Solar cell", "electrical", "light"], ["Torch", "electrical", "light"]], [100, 90, 130], "Four devices"))
q("ec-115", I, 2, EC, "A book is lifted from the floor and put on a high shelf. Which statement about the book is correct?", "Its potential energy has increased because it is higher", [W("Its kinetic energy has increased because it was moved", "wrong-idea", "On the shelf the book is at rest, so it has no kinetic energy."), W("Its potential energy has decreased because it is further from the floor", "reversed", "The higher an object is, the more potential energy it has."), W("It has gained no energy because it is at rest", "wrong-idea", "Being high up gives it potential energy even when it is at rest.")], ["Lifting the book needs energy, which is stored as gravitational potential energy."], None)
q("ec-116", I, 1, EC, "Dina eats her breakfast and then runs. What happens to the energy stored in her food?", "It changes into kinetic energy and heat in her body", [W("It changes into light energy in her muscles", "wrong-form", "Muscles do not give out light."), W("It changes into electrical energy and stays in her muscles", "wrong-idea", "Her body does not store energy as electricity for running."), W("It is lost as sound when she breathes", "wrong-idea", "Only a tiny part of the energy leaves as sound.")], ["The energy stored in food is used for movement (kinetic energy) and keeps the body warm (heat)."], None)
q("ec-117", I, 3, EC, "Which pair of devices shows the main energy conversions correctly?", "Electric fan: electrical to kinetic; solar panel: light to electrical", [W("Electric fan: kinetic to electrical; solar panel: light to electrical", "reversed", "A fan uses electricity to move. It does not make electricity."), W("Electric fan: electrical to kinetic; solar panel: electrical to light", "reversed", "A solar panel changes light into electricity."), W("Electric fan: electrical to heat; solar panel: heat to electrical", "wrong-form", "A fan mainly makes movement, and a solar panel uses light.")], ["Both conversions in the correct row are right."], None)
q("ec-118", I, 3, EC, "A filament bulb is hot after it has been switched on for a while. Why?", "Some of the electrical energy is changed into heat energy", [W("The bulb takes in heat energy from the room", "wrong-idea", "The heat comes from the bulb itself."), W("All the light energy is changed into heat energy", "wrong-idea", "Some energy still leaves as light, and the light comes from electrical energy."), W("The bulb stores kinetic energy", "wrong-form", "Nothing inside the bulb is moving to store kinetic energy.")], ["A bulb changes electrical energy into light and heat."], None)
q("ec-119", I, 3, EC, "Water stored high behind a dam flows down to turn a turbine, which turns a generator. Which row shows the order of the energy conversions?", "Potential energy, kinetic energy, electrical energy", [W("Kinetic energy, potential energy, electrical energy", "wrong-order", "The water is high first, so it has potential energy first."), W("Electrical energy, kinetic energy, potential energy", "reversed", "A generator makes electricity at the end of the chain."), W("Potential energy, electrical energy, kinetic energy", "wrong-order", "The turbine moves before the generator makes electricity.")], ["Water high up has potential energy, moving water has kinetic energy, and the generator makes electrical energy."], None)
q("ec-120", I, 3, EC, "A diver jumps from the end of the bent springboard shown. As the board straightens and pushes the diver up, which energy conversion mainly takes place?", "Elastic potential energy of the board to kinetic energy of the diver", [W("Kinetic energy of the diver to elastic potential energy of the board", "reversed", "That happens when the diver lands on the board. Here the board is pushing the diver up."), W("Heat energy of the board to kinetic energy of the diver", "wrong-form", "The board is not hot. It is bent."), W("Light energy to kinetic energy of the diver", "wrong-form", "The diver does not use light energy to jump.")], ["The bent board stores elastic potential energy, which becomes the diver's kinetic energy."], springboard)
q("ec-121", I, 2, EC, "A ball is thrown straight up. At its highest point, which statement is correct?", "Its kinetic energy is the least and its potential energy is the greatest", [W("Its kinetic energy is the greatest and its potential energy is the least", "reversed", "At the top the ball stops for a moment, so kinetic energy is the least."), W("Its kinetic energy and potential energy are both zero", "wrong-idea", "It is high up, so it has a lot of potential energy."), W("Its kinetic energy and potential energy are both the greatest", "wrong-idea", "It has stopped for a moment, so its kinetic energy is the least.")], ["At the top the ball is highest and momentarily at rest."], None)
q("ec-122", I, 1, EC, "Which sequence best shows how the energy in petrol came from the Sun?", "Sunlight, plants long ago, buried remains, petrol", [W("Sunlight, water in the sea, rain collected underground, petrol", "wrong-idea", "Petrol is not made from rain."), W("Sunlight, wind, rocks that melt underground, petrol", "wrong-idea", "Petrol is not formed from the wind or from rocks warmed by the Sun."), W("Sunlight, the Moon, soil that is pressed, petrol", "wrong-idea", "The Moon and soil are not part of how petrol is formed.")], ["Plants and animals that lived long ago got their energy from the Sun. Their remains were buried and slowly changed into fuels."], None)
q("ec-123", I, 1, EC, "Hana says that the energy in the food we eat comes from the Sun. Which statement supports her?", "Plants use sunlight to make food, and we eat plants or animals that ate them", [W("The Sun cooks the food and the heat stays stored in it", "wrong-idea", "That heat does not give the food its stored energy."), W("Animals take in energy straight from the soil they walk on", "wrong-idea", "Animals do not get their energy from soil."), W("Food stores up heat that it takes in from the warm air", "wrong-idea", "Food does not take heat from the air.")], ["The energy in food started as light energy from the Sun that plants used to make food."], None)
