q("ec-125", I, 3, EC, "A hand warmer is switched on and becomes warm. Which energy conversion takes place?", cv("Electrical", "heat"), [W(cv("Heat", "electrical"), "reversed", "The device makes heat from electricity."), W(cv("Light", "heat"), "wrong-form", "The hand warmer is not powered by light."), W(cv("Kinetic", "electrical"), "wrong-form", "Nothing in a hand warmer moves to make electricity.")], ["Electric current heats the warmer."], None)

