KEPE = lambda: graph(["0", "1", "2", "3", "4"], [("Kinetic", [0, 6, 25, 56, 100]), ("Potential", [100, 94, 75, 44, 0])], 120, "Time (s)", "Energy (units)", "A ball falling from a high place", ystep=20, W=360, H=250)
